   const result=await (0,eval)("// t217 - GB-144 (Jerry, 2026-10-08: "look at all the suppressors. Make them fit the guns better").
// Each of the six cans (CL-95) is measured against its gun's real geometry, in the gun's own space:
// - the can is coaxial with the bore (the barrel or muzzle device's cross-section is centred on the can's axis);
// - its back face sits on the muzzle device: not in front of the barrel's end (no gap), and everything of the gun
//   inside its sleeve is round about the bore and inside the can (no front sight, brake corner or slide in it);
// - nothing of the gun pokes through the can, its size is in proportion to the barrel, and with it on the muzzle
//   point and the flash sit on its front end; off, they go back.
(async () => {
  const T = window.TT, THREE = T.THREE, out = [];
  const ok = (c, m) => out.push((c ? 'PASS ' : 'FAIL ') + m);
  const mm = (v) => (v * 1000).toFixed(1) + ' mm';
  // where to read the bore (gun-local z) and how far round it to look: just the barrel or muzzle device there
  const PROBE = { m4: [0.95, 0.02], ak: [0.99, 0.025], pistol: [0.25, 0.016], uzi: [0.44, 0.02], sniper: [1.05, 0.025], shotgun: [0.93, 0.04] };
