      if (!ud || !ud.suppressor || !S) { ok(false, key + ': no can built'); continue; }
      T.setGunSuppressor(gun, false);
      const skip = new Set([ud.suppressor, ud.flash, ud.flashLight, ud.laser, ud.heavyLook].filter(Boolean));
      gun.updateMatrixWorld(true);
      const inv = new THREE.Matrix4().copy(gun.matrixWorld).invert();
      const tris = [];
      const walk = (o) => {
        if (skip.has(o) || o.visible === false) return;
        if (o.isMesh && o.geometry && o.geometry.attributes && o.geometry.attributes.position) {
          const m = new THREE.Matrix4().multiplyMatrices(inv, o.matrixWorld), p = o.geometry.attributes.position, idx = o.geometry.index, v = new THREE.Vector3(), V = [];
          for (let i = 0; i < p.count; i++) { v.set(p.getX(i), p.getY(i), p.getZ(i)).applyMatrix4(m); V.push([v.x, v.y, v.z]); }
          const n = idx ? idx.count : p.count, gi = (i) => (idx ? (idx.getX ? idx.getX(i) : idx.array[i]) : i);
          for (let i = 0; i + 2 < n; i += 3) tris.push([V[gi(i)], V[gi(i + 1)], V[gi(i + 2)]]);
        }
        for (const c of o.children) walk(c);
      };
      for (const c of gun.children) walk(c);
      const slice = (z) => {
        const pts = [];
        for (const t of tris) for (let e = 0; e < 3; e++) {
          const a = t[e], b = t[(e + 1) % 3];
          if (a[2] !== b[2] && (a[2] - z) * (b[2] - z) <= 0) { const u = (z - a[2]) / (b[2] - a[2]); pts.push([a[0] + (b[0] - a[0]) * u, a[1] + (b[1] - a[1]) * u]); }
        }
        return pts;
      };
      const can = ud.suppressor;
      const ax = can.position.x, ay = can.position.y, back = can.position.z, front = back + S.len;
      const box = (pts) => { const b = [1e9, -1e9, 1e9, -1e9]; for (const p of pts) { b[0] = Math.min(b[0], p[0]); b[1] = Math.max(b[1], p[0]); b[2] = Math.min(b[2], p[1]); b[3] = Math.max(b[3], p[1]); } return b; };
      // the bore, from the barrel or muzzle device's cross-section
      const [pz, pr] = PROBE[key];
      const bore = slice(pz).filter((p) => Math.hypot(p[0] - ax, p[1] - ay) < pr);
      const bb = box(bore), bx = (bb[0] + bb[1]) / 2, by = (bb[2] + bb[3]) / 2, barrelR = Math.max(bb[1] - bb[0], bb[3] - bb[2]) / 2;
